From 4561858e8bfa67c7a56cab85d92ac754a30b8205 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 02:49:53 +0100
Subject: [PATCH] applets/notifications: keep job details available after the
 job finishes

Once a job stopped its Details button was hidden, so the source, sizes
and timing seen during a copy were lost. Keep it next to the file
actions, showing the average speed and how long the job took.

BUG: 436410
---
 .../notifications/components/JobDetails.qml   | 29 +++++-
 applets/notifications/components/JobItem.qml  | 99 +++++++++----------
 2 files changed, 75 insertions(+), 53 deletions(-)

diff --git a/applets/notifications/components/JobDetails.qml b/applets/notifications/components/JobDetails.qml
index e6d5c08dc2..f0a390d625 100644
--- a/applets/notifications/components/JobDetails.qml
+++ b/applets/notifications/components/JobDetails.qml
@@ -34,6 +34,19 @@ GridLayout {
         }
     }

+    readonly property bool finished: modelInterface.jobState === NotificationManager.Notifications.JobStateStopped
+    // Once the job has finished, the last reported speed is stale, so show the average one instead.
+    readonly property real speed: {
+        const details = modelInterface.jobDetails;
+        if (!details) {
+            return 0;
+        }
+        if (finished) {
+            return details.elapsedTime > 0 ? details.processedBytes / details.elapsedTime * 1000 : 0;
+        }
+        return details.speed;
+    }
+
     columns: 2
     rowSpacing: Math.round(Kirigami.Units.smallSpacing / 2)
     columnSpacing: Kirigami.Units.smallSpacing
@@ -170,10 +183,22 @@ GridLayout {
         Layout.column: 1
         Layout.row: 2 + 4
         Layout.fillWidth: true
-        text: detailsGrid.modelInterface.jobDetails?.speed > 0 ? i18ndc("plasma_applet_org.kde.plasma.notifications", "Bytes per second", "%1/s",
-            KCoreAddons.Format.formatByteSize(detailsGrid.modelInterface.jobDetails.speed)) : ""
+        text: detailsGrid.speed > 0 ? i18ndc("plasma_applet_org.kde.plasma.notifications", "Bytes per second", "%1/s",
+            KCoreAddons.Format.formatByteSize(detailsGrid.speed)) : ""
         font: Kirigami.Theme.smallFont
         textFormat: Text.PlainText
         visible: text !== "" && !detailsGrid.chartVisible
     }
+
+    PlasmaExtras.DescriptiveLabel {
+        Layout.column: 1
+        Layout.row: 2 + 5
+        Layout.fillWidth: true
+        text: detailsGrid.finished && detailsGrid.modelInterface.jobDetails?.elapsedTime > 0
+            ? i18ndc("plasma_applet_org.kde.plasma.notifications", "How long the job took, e.g. Took 2 minutes and 5 seconds", "Took %1",
+                KCoreAddons.Format.formatSpelloutDuration(detailsGrid.modelInterface.jobDetails.elapsedTime)) : ""
+        font: Kirigami.Theme.smallFont
+        textFormat: Text.PlainText
+        visible: text !== ""
+    }
 }
diff --git a/applets/notifications/components/JobItem.qml b/applets/notifications/components/JobItem.qml
index 3e0efe8c39..af3b0784e6 100644
--- a/applets/notifications/components/JobItem.qml
+++ b/applets/notifications/components/JobItem.qml
@@ -27,6 +27,8 @@ ColumnLayout {

     readonly property alias menuOpen: otherFileActionsMenu.visible

+    readonly property bool hasFileActions: (modelInterface.jobDetails?.effectiveDestUrl.toString() ?? "") !== "" && !fileInfo.error
+
     spacing: Kirigami.Units.smallSpacing

     Notifications.FileInfo {
@@ -93,33 +95,43 @@ ColumnLayout {
             text: i18ndc("plasma_applet_org.kde.plasma.notifications", "Cancel running job", "Cancel")
             onClicked: jobItem.modelInterface.killJobClicked()
         }
-    }

-    Loader {
-        Layout.fillWidth: true
-        Layout.preferredWidth: Notifications.Globals.popupWidth
-        Layout.preferredHeight: item ? (item as Item).implicitHeight : 0
-        active: expandButton.checked
-        // Loader doesn't reset its height when unloaded, just hide it altogether
-        visible: active
-        sourceComponent: JobDetails {
-            modelInterface: jobItem.modelInterface
-            chartVisible: speedChart.chartVisible
-        }
-    }
+        PlasmaComponents3.Button {
+            id: openButton
+            Layout.fillWidth: true
+            Layout.maximumWidth: implicitWidth
+            Layout.fillHeight: true
+            visible: jobItem.hasFileActions
+            text: i18nd("plasma_applet_org.kde.plasma.notifications", "Open")
+            onClicked: jobItem.modelInterface.openUrl(jobItem.modelInterface.jobDetails.effectiveDestUrl)

-    Row {
-        id: fileActionsRow
-        Layout.fillWidth: true
-        spacing: Kirigami.Units.smallSpacing
-        // We want the actions to be right-aligned but Row also reverses
-        // the order of items, so we put them in reverse order
-        layoutDirection: Qt.RightToLeft
-        visible: (jobItem.modelInterface.jobDetails?.effectiveDestUrl.toString() ?? "") !== "" && !fileInfo.error
+            states: [
+                State {
+                    when: jobItem.modelInterface.jobDetails && jobItem.modelInterface.jobDetails.totalFiles !== 1
+                    PropertyChanges {
+                        openButton.text: i18nd("plasma_applet_org.kde.plasma.notifications", "Open Containing Folder")
+                        openButton.icon.name: "folder-open-symbolic"
+                    }
+                },
+                State {
+                    when: fileInfo.openAction !== null
+                    PropertyChanges {
+                        openButton.text: fileInfo.openAction.text
+                        openButton.icon.name: fileInfo.openActionIconName
+                        openButton.visible: jobItem.hasFileActions && fileInfo.openAction.enabled
+                        openButton.onClicked: {
+                            fileInfo.openAction.trigger();
+                            jobItem.modelInterface.fileActionInvoked(fileInfo.openAction);
+                        }
+                    }
+                }
+            ]
+        }

         PlasmaComponents3.Button {
             id: otherFileActionsButton
-            height: Math.max(implicitHeight, openButton.implicitHeight)
+            Layout.fillHeight: true
+            visible: jobItem.hasFileActions
             icon.name: "application-menu-symbolic"
             checkable: true
             text: openButton.visible ? "" : Accessible.name
@@ -146,35 +158,18 @@ ColumnLayout {
                 onActionTriggered: action => jobItem.modelInterface.fileActionInvoked(action)
             }
         }
+    }

-        PlasmaComponents3.Button {
-            id: openButton
-            width: Math.min(implicitWidth, jobItem.width - otherFileActionsButton.width - fileActionsRow.spacing)
-            height: Math.max(implicitHeight, otherFileActionsButton.implicitHeight)
-            text: i18nd("plasma_applet_org.kde.plasma.notifications", "Open")
-            onClicked: jobItem.modelInterface.openUrl(jobItem.modelInterface.jobDetails.effectiveDestUrl)
-
-            states: [
-                State {
-                    when: jobItem.modelInterface.jobDetails && jobItem.modelInterface.jobDetails.totalFiles !== 1
-                    PropertyChanges {
-                        openButton.text: i18nd("plasma_applet_org.kde.plasma.notifications", "Open Containing Folder")
-                        openButton.icon.name: "folder-open-symbolic"
-                    }
-                },
-                State {
-                    when: fileInfo.openAction !== null
-                    PropertyChanges {
-                        openButton.text: fileInfo.openAction.text
-                        openButton.icon.name: fileInfo.openActionIconName
-                        openButton.visible: fileInfo.openAction.enabled
-                        openButton.onClicked: {
-                            fileInfo.openAction.trigger();
-                            jobItem.modelInterface.fileActionInvoked(fileInfo.openAction);
-                        }
-                    }
-                }
-            ]
+    Loader {
+        Layout.fillWidth: true
+        Layout.preferredWidth: Notifications.Globals.popupWidth
+        Layout.preferredHeight: item ? (item as Item).implicitHeight : 0
+        active: expandButton.checked
+        // Loader doesn't reset its height when unloaded, just hide it altogether
+        visible: active
+        sourceComponent: JobDetails {
+            modelInterface: jobItem.modelInterface
+            chartVisible: speedChart.chartVisible
         }
     }

@@ -191,7 +186,9 @@ ColumnLayout {
                 speedChart.visible: false
             }
             PropertyChanges {
-                jobActionsRow.visible: false
+                jobActionsRow.visible: expandButton.checkable || jobItem.hasFileActions
+                suspendButton.visible: false
+                killButton.visible: false
             }
             PropertyChanges {
                 expandButton.checked: false
-- 
